    # 8.1.4 安全计算环境（11 个控制点，34 项）
    # =========================================================================
    ("8.1.4.1-a", "安全计算环境", "身份鉴别", "应对登录的用户进行身份标识和鉴别，身份标识具有唯一性，身份鉴别信息具有复杂度要求并定期更换。", "GENERAL", "FULL_AUTO", True, ["ssh_baseline"], "依据主机口令复杂度、最小长度、有效期、空口令及账号唯一性基线核查结果评估，并补充核对数据库与业务应用。"),
    ("8.1.4.1-b", "安全计算环境", "身份鉴别", "应具有登录失败处理功能，应配置并启用结束会话、限制非法登录次数和当登录连接超时自动退出等相关措施。", "GENERAL", "FULL_AUTO", True, ["ssh_baseline"], "依据主机 pam_faillock 锁定阈值/时长、SSH 空闲断开及 TMOUT 会话超时核查结果评估。"),
    ("8.1.4.1-c", "安全计算环境", "身份鉴别", "当进行远程管理时，应采取必要措施防止鉴别信息在网络传输过程中被窃听。", "GENERAL", "FULL_AUTO", True, ["ssh_baseline", "tls_scanner"], "核对 SSH 协议版本、弱加密算法、root 远程登录限制及 Web 管理台 HTTPS 加密配置。"),
    ("8.1.4.1-d", "安全计算环境", "身份鉴别", "应采用口令、密码技术、生物技术等两种或两种以上组合的鉴别技术对用户进行身份鉴别，且其中一种鉴别技术至少应使用密码技术来实现。", "GENERAL", "PARTIAL_EVIDENCE", True, ["ssh_baseline"], "核查堡垒机、服务器及关键业务后台是否启用双因子认证（如口令加动态令牌/数字证书/硬件 Key）。"),
    ("8.1.4.2-a", "安全计算环境", "访问控制", "应对登录的用户分配账户和权限。", "GENERAL", "PARTIAL_EVIDENCE", False, ["ssh_baseline"], "核查操作系统、数据库及应用系统账户与权限分配表，确认按岗位授予对应角色。"),
    ("8.1.4.2-b", "安全计算环境", "访问控制", "应重命名或删除默认账户，修改默认账户的默认口令。", "GENERAL", "PARTIAL_EVIDENCE", True, ["ssh_baseline"], "结合主机默认账户与系统账户登录 Shell 核查结果，补充检查数据库和中间件默认口令修改情况。"),
    ("8.1.4.2-c", "安全计算环境", "访问控制", "应及时删除或停用多余的、过期的账户，避免共享账户的存在。", "GENERAL", "FULL_AUTO", True, ["ssh_baseline"], "核查操作系统非 root 的 UID 0 账户、可登录系统账户及多余/共享账号清理记录。"),
    ("8.1.4.2-d", "安全计算环境", "访问控制", "应授予管理用户所需的最小权限，实现管理用户的权限分离。", "GENERAL", "FULL_AUTO", True, ["ssh_baseline"], "依据主机 sudo 免密提权、特权账户配置核查结果评估，并核对系统/安全/审计三员权限分离。"),
    ("8.1.4.2-e", "安全计算环境", "访问控制", "应由授权主体配置访问控制策略，访问控制策略规定主体对客体的访问规则。", "GENERAL", "PARTIAL_EVIDENCE", False, ["ssh_baseline"], "核查授权管理员配置访问控制策略的机制及权限变更审批记录。"),
    ("8.1.4.2-f", "安全计算环境", "访问控制", "访问控制的粒度应达到主体为用户级或进程级，客体为文件、数据库表级。", "GENERAL", "FULL_AUTO", False, ["ssh_baseline"], "依据关键系统文件权限（/etc/passwd、/etc/shadow、sudoers）、umask 及临时目录粘滞位结果评估。"),
    ("8.1.4.2-g", "安全计算环境", "访问控制", "应对重要主体和客体设置安全标记，并控制主体对有安全标记信息资源的访问。", "GENERAL", "PARTIAL_EVIDENCE", False, ["ssh_baseline"], "结合主机 SELinux/AppArmor 强制访问控制状态，核查重要数据主体与客体的安全标记配置。"),
    ("8.1.4.3-a", "安全计算环境", "安全审计", "应启用安全审计功能，审计覆盖到每个用户，对重要的用户行为和重要安全事件进行审计。", "GENERAL", "FULL_AUTO", True, ["ssh_baseline"], "依据主机 auditd 与 rsyslog 服务运行状态、审计规则覆盖范围评估，并补充核对数据库及应用审计。"),
    ("8.1.4.3-b", "安全计算环境", "安全审计", "审计记录应包括事件的日期和时间、用户、事件类型、事件是否成功及其他与审计相关的信息。", "GENERAL", "PARTIAL_EVIDENCE", False, ["ssh_baseline"], "抽查主机审计日志、数据库审计日志与应用操作日志样本，核对必备字段完整性。"),
    ("8.1.4.3-c", "安全计算环境", "安全审计", "应对审计记录进行保护，定期备份，避免受到未预期的删除、修改或覆盖等。", "GENERAL", "PARTIAL_EVIDENCE", True, ["ssh_baseline"], "结合日志轮转、写满动作及远程转发配置，补充核验集中日志平台六个月以上留存与防篡改保护。"),
    ("8.1.4.3-d", "安全计算环境", "安全审计", "应对审计进程进行保护，防止未经授权的中断。", "GENERAL", "PARTIAL_EVIDENCE", True, ["ssh_baseline"], "核查 auditd 不可变规则（-e 2）或审计进程权限隔离，确保普通及非授权用户无法中止审计。"),
    ("8.1.4.4-a", "安全计算环境", "入侵防范", "应遵循最小安装的原则，仅安装需要的组件和应用程序。", "GENERAL", "PARTIAL_EVIDENCE", False, ["ssh_baseline", "trivy_os"], "抽查已安装软件包清单，确认未安装与生产业务无关的编译工具、测试组件或多余应用。"),
    ("8.1.4.4-b", "安全计算环境", "入侵防范", "应关闭不需要的系统服务、默认共享和高危端口。", "GENERAL", "FULL_AUTO", True, ["ssh_baseline", "nmap"], "依据主机传统不必要网络服务检查与 Nmap 端口暴露扫描结果评估。"),
    ("8.1.4.4-c", "安全计算环境", "入侵防范", "应通过设定终端接入方式或网络地址范围对通过网络进行管理的管理终端进行限制。", "GENERAL", "PARTIAL_EVIDENCE", True, ["ssh_baseline", "nmap"], "核查 SSH AllowUsers/TCP Wrappers、防火墙管理源地址白名单及堡垒机唯一入口限制。"),
    ("8.1.4.4-d", "安全计算环境", "入侵防范", "应提供数据有效性检验功能，保证通过人机接口输入或通过通信接口输入的内容符合系统设定要求。", "GENERAL", "PARTIAL_EVIDENCE", False, ["nuclei"], "结合 Web 模板漏洞扫描结果与代码/接口测试报告，核查 SQL 注入、XSS 与参数校验防护。"),
    ("8.1.4.4-e", "安全计算环境", "入侵防范", "应能发现可能存在的已知漏洞，并在经过充分测试评估后，及时修补漏洞。", "GENERAL", "FULL_AUTO", True, ["trivy_os", "nuclei", "ssh_baseline"], "依据操作系统软件包 CVE 清单、Web 已知漏洞结果与安全更新修补情况评估。"),
    ("8.1.4.4-f", "安全计算环境", "入侵防范", "应能够检测到对重要节点进行入侵的行为，并在发生严重入侵事件时提供报警。", "GENERAL", "PARTIAL_EVIDENCE", True, ["ssh_baseline"], "核查主机入侵检测系统（HIDS/EDR）部署状态、文件完整性监控及严重入侵实时告警配置。"),
    ("8.1.4.5-a", "安全计算环境", "恶意代码防范", "应采用免受恶意代码攻击的技术措施或主动免疫可信验证机制及时识别入侵和病毒行为，并将其有效阻断。", "GENERAL", "PARTIAL_EVIDENCE", True, ["ssh_baseline"], "核查主机防病毒或 EDR 进程运行状态、特征库更新周期及实时拦截记录。"),
    ("8.1.4.6-a", "安全计算环境", "可信验证", "可基于可信根对计算设备的系统引导程序、系统程序、重要配置参数和应用程序等进行可信验证，并在应用程序的关键执行环节进行动态可信验证，在检测到其可信性受到破坏后进行报警，并将验证结果形成审计记录送至安全管理中心。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "核查服务器 TPM/TCM 可信芯片、安全启动（Secure Boot）及可信度量审计能力。"),
    ("8.1.4.7-a", "安全计算环境", "数据完整性", "应采用校验技术或密码技术保证重要数据在传输过程中的完整性，包括但不限于鉴别数据、重要业务数据、重要审计数据、重要配置数据、重要视频数据和重要个人信息等。", "GENERAL", "PARTIAL_EVIDENCE", True, ["tls_scanner"], "结合 TLS 传输校验算法核查结果，补充核验内部 API、文件传输与消息队列的完整性校验机制。"),
    ("8.1.4.7-b", "安全计算环境", "数据完整性", "应采用校验技术或密码技术保证重要数据在存储过程中的完整性，包括但不限于鉴别数据、重要业务数据、重要审计数据、重要配置数据、重要视频数据和重要个人信息等。", "GENERAL", "MANUAL_ONLY", True, ["manual"], "核查数据库、文件存储与审计日志是否采用 MAC、数字签名或哈希校验防止存储篡改。"),
    ("8.1.4.8-a", "安全计算环境", "数据保密性", "应采用密码技术保证重要数据在传输过程中的保密性，包括但不限于鉴别数据、重要业务数据和重要个人信息等。", "GENERAL", "PARTIAL_EVIDENCE", True, ["tls_scanner", "ssh_baseline"], "核查业务 HTTPS、远程 SSH 及数据库通信链路是否采用安全密码算法加密传输。"),
    ("8.1.4.8-b", "安全计算环境", "数据保密性", "应采用密码技术保证重要数据在存储过程中的保密性，包括但不限于鉴别数据、重要业务数据和重要个人信息等。", "GENERAL", "MANUAL_ONLY", True, ["manual"], "核查口令加盐哈希、数据库敏感字段加密（SM4/AES）及配置文件密钥保护措施。"),
    ("8.1.4.9-a", "安全计算环境", "数据备份恢复", "应提供重要数据的本地数据备份与恢复功能。", "GENERAL", "MANUAL_ONLY", True, ["manual"], "查验数据库与核心文件本地定时备份任务配置、备份文件留存及恢复测试记录。"),
    ("8.1.4.9-b", "安全计算环境", "数据备份恢复", "应提供异地实时备份功能，利用通信网络将重要数据实时备份至备份场地。", "GENERAL", "MANUAL_ONLY", True, ["manual"], "查验异地容灾备份链路、实时/准实时同步监控及最近一次异地恢复验证记录。"),
    ("8.1.4.9-c", "安全计算环境", "数据备份恢复", "应提供重要数据处理系统的热冗余，保证系统的高可用性。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "核查核心业务应用集群、数据库主备/高可用架构及故障自动切换演练记录。"),
    ("8.1.4.10-a", "安全计算环境", "剩余信息保护", "应保证鉴别信息所在的存储空间被释放或重新分配前得到完全清除。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "核查退出登录或会话超时后前端 Cookie/Token 及后端内存鉴别凭据的清除机制。"),
    ("8.1.4.10-b", "安全计算环境", "剩余信息保护", "应保证存有敏感数据的存储空间被释放或重新分配前得到完全清除。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "核查数据库记录清理、临时文件销毁及磁盘回收前的安全覆写机制。"),
    ("8.1.4.11-a", "安全计算环境", "个人信息保护", "应仅采集和保存业务必需的用户个人信息。", "GENERAL", "MANUAL_ONLY", True, ["manual"], "核查业务系统个人信息采集清单、隐私政策及最小必要原则合规性说明。"),
    ("8.1.4.11-b", "安全计算环境", "个人信息保护", "应禁止未授权访问和非法使用用户个人信息。", "GENERAL", "MANUAL_ONLY", True, ["manual"], "核查个人信息脱敏展示、导出审批、查询审计及接口越权防护措施。"),

    # =========================================================================
    # 8.1.5 安全管理中心（4 个控制点，12 项）
    # =========================================================================
    ("8.1.5.1-a", "安全管理中心", "系统管理", "应对系统管理员进行身份鉴别，只允许其通过特定的命令或操作界面进行系统管理操作，并对这些操作进行审计。", "GENERAL", "PARTIAL_EVIDENCE", True, ["ssh_baseline"], "核查系统管理员通过堡垒机/专用运维界面鉴权登录及全过程命令录像审计情况。"),
    ("8.1.5.1-b", "安全管理中心", "系统管理", "应通过系统管理员对系统的资源和运行进行配置、控制和管理，包括用户身份、系统资源配置、系统加载和启动、系统运行的异常处理、数据和设备的备份与恢复等。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "核查系统管理员权限范围及日常资源配置、异常处理、备份恢复操作记录。"),
    ("8.1.5.2-a", "安全管理中心", "审计管理", "应对审计管理员进行身份鉴别，只允许其通过特定的命令或操作界面进行安全审计操作，并对这些操作进行审计。", "GENERAL", "MANUAL_ONLY", True, ["manual"], "核查审计管理员专用审计界面、独立认证机制及审计自身操作留痕。"),
    ("8.1.5.2-b", "安全管理中心", "审计管理", "应通过审计管理员对审计记录进行分析，并根据分析结果进行处理，包括根据安全审计策略对审计记录进行存储、管理和查询等。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "查阅审计管理员定期开展日志分析、异常排查及审计报表留存记录。"),
    ("8.1.5.3-a", "安全管理中心", "安全管理", "应对安全管理员进行身份鉴别，只允许其通过特定的命令或操作界面进行安全管理操作，并对这些操作进行审计。", "GENERAL", "MANUAL_ONLY", True, ["manual"], "核查安全管理员独立鉴别、专用策略管理界面及操作审计记录。"),
    ("8.1.5.3-b", "安全管理中心", "安全管理", "应通过安全管理员对系统中的安全策略进行配置，包括安全参数的设置，主体、客体进行统一安全标记，对主体进行授权，配置可信验证策略等。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "核查安全管理员对访问策略、安全参数与主体授权的统一配置及复核记录。"),
    ("8.1.5.4-a", "安全管理中心", "集中管控", "应划分出特定的管理区域，对分布在网络中的安全设备或安全组件进行管控。", "GENERAL", "MANUAL_ONLY", True, ["manual"], "核查网络拓扑中是否划设独立运维管理区（带外或专用管理网段）集中管理安全设备。"),
    ("8.1.5.4-b", "安全管理中心", "集中管控", "应能够建立一条安全的信息传输路径，对网络中的安全设备或安全组件进行管理。", "GENERAL", "PARTIAL_EVIDENCE", True, ["ssh_baseline", "tls_scanner"], "核查运维管理通道是否采用 HTTPS/SSH/IPSec VPN 等加密协议，禁用 Telnet/HTTP 明文管理。"),
    ("8.1.5.4-c", "安全管理中心", "集中管控", "应对网络链路、安全设备、网络设备和服务器等的运行状况进行集中监测。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "查验网管/监控平台（如 Zabbix、Prometheus 等）对链路、网络设备、安全设备与主机的运行监测画面。"),
    ("8.1.5.4-d", "安全管理中心", "集中管控", "应对分散在各个设备上的审计数据进行收集汇总和集中分析，并保证审计记录的留存时间符合法律法规要求。", "GENERAL", "PARTIAL_EVIDENCE", True, ["ssh_baseline"], "结合主机 rsyslog 集中转发与时间同步核查，查验日志审计/SIEM 平台汇总分析与六个月以上留存证据。"),
    ("8.1.5.4-e", "安全管理中心", "集中管控", "应对安全策略、恶意代码、补丁升级等安全相关事项进行集中管理。", "GENERAL", "PARTIAL_EVIDENCE", False, ["trivy_os", "defectdojo"], "核查终端防病毒管理中心、补丁分发平台及漏洞整改跟踪台账的统一管控情况。"),
    ("8.1.5.4-f", "安全管理中心", "集中管控", "应能对网络中发生的各类安全事件进行识别、报警和分析。", "GENERAL", "MANUAL_ONLY", True, ["manual"], "查验 SIEM/SOC/态势感知平台的安全事件关联规则、报警记录与处置工单闭环。"),

    # =========================================================================
    # 8.1.6 安全管理制度（4 个控制点，7 项）
    # =========================================================================
    ("8.1.6.1-a", "安全管理制度", "安全策略", "应制定网络安全工作的总体方针和安全策略，阐明机构安全工作的总体目标、范围、原则和安全框架等。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "查阅经单位管理层签发生效的《网络安全总体方针与安全策略》正式文件。"),
    ("8.1.6.2-a", "安全管理制度", "管理制度", "应对安全管理活动中的各类管理内容建立安全管理制度。", "GENERAL", "MANUAL_ONLY", True, ["manual"], "核查覆盖机房、网络、账号、变更、备份、应急等活动的安全管理制度汇编。"),
    ("8.1.6.2-b", "安全管理制度", "管理制度", "应对管理人员或操作人员执行的日常管理操作建立操作规程。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "抽查账号开通、配置变更、系统巡检、数据备份与漏洞修补等标准操作规程（SOP）。"),
    ("8.1.6.2-c", "安全管理制度", "管理制度", "应形成由安全策略、管理制度、操作规程、记录表单等构成的全面的安全管理制度体系。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "核查四级制度体系文件目录及配套运行记录表单是否完整对应。"),
    ("8.1.6.3-a", "安全管理制度", "制定和发布", "应指定或授权专门的部门或人员负责安全管理制度的制定。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "查验制度编制职责授权文件及起草、会签流程记录。"),
    ("8.1.6.3-b", "安全管理制度", "制定和发布", "安全管理制度应通过正式、有效的方式发布，并进行版本控制。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "核查制度红头发文/OA 公告截图、签发审批单、版本号及收发受控登记表。"),
    ("8.1.6.4-a", "安全管理制度", "评审和修订", "应定期对安全管理制度的合理性和适用性进行论证和审定，对存在不足或需要改进的安全管理制度进行修订。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "查阅年度安全管理制度评审纪要、修订对照表及新版制度发布记录。"),

    # =========================================================================
    # 8.1.7 安全管理机构（5 个控制点，14 项）
    # =========================================================================
    ("8.1.7.1-a", "安全管理机构", "岗位设置", "应成立指导和管理网络安全工作的委员会或领导小组，其最高领导由单位主管领导担任或授权。", "GENERAL", "MANUAL_ONLY", True, ["manual"], "查阅网络安全领导小组成立发文、成员名单及主管领导任命说明。"),
    ("8.1.7.1-b", "安全管理机构", "岗位设置", "应设立网络安全管理工作的职能部门，设立安全主管、安全管理各个方面的负责人岗位，并定义各负责人的职责。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "查验网络安全职能部门组织架构图及各安全负责人岗位说明书。"),
    ("8.1.7.1-c", "安全管理机构", "岗位设置", "应设立系统管理员、审计管理员和安全管理员等岗位，并定义部门及各个工作岗位的职责。", "GENERAL", "MANUAL_ONLY", True, ["manual"], "核查三员岗位设置文件与职责边界定义，确认权责清晰且相互制衡。"),
    ("8.1.7.2-a", "安全管理机构", "人员配备", "应配备一定数量的系统管理员、审计管理员和安全管理员等。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "查验三员在岗人员花名册、联系方式及实际履职记录。"),
    ("8.1.7.2-b", "安全管理机构", "人员配备", "应配备专职安全管理员，不可兼任。", "GENERAL", "MANUAL_ONLY", True, ["manual"], "核查专职安全管理员任命文件，确认未与系统管理员或审计管理员兼任。"),
    ("8.1.7.3-a", "安全管理机构", "授权和审批", "应根据各个部门和岗位的职责明确授权审批事项、审批部门和批准人等。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "查阅授权审批矩阵表，核对权限申请、系统变更、物理进入等事项的审批人。"),
    ("8.1.7.3-b", "安全管理机构", "授权和审批", "应针对系统变更、重要操作、物理访问和系统接入等事项建立审批程序，按照审批程序执行审批过程，对重要活动建立逐级审批制度。", "GENERAL", "MANUAL_ONLY", True, ["manual"], "抽查近半年变更单、高危操作单、机房进出单和接入申请单的逐级审批记录。"),
    ("8.1.7.3-c", "安全管理机构", "授权和审批", "应定期审查审批事项，及时更新需授权和审批的项目、审批部门和审批人等信息。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "查阅年度审批事项与审批人清单复查记录及变更更新日志。"),
    ("8.1.7.4-a", "安全管理机构", "沟通和合作", "应加强各类管理人员、组织内部机构和网络安全管理部门之间的合作与沟通，定期召开协调会议，共同协作处理网络安全问题。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "查阅内部网络安全协调会议纪要、签到表及跨部门风险沟通记录。"),
    ("8.1.7.4-b", "安全管理机构", "沟通和合作", "应加强与网络安全职能部门、各类供应商、业界专家及安全组织的合作与沟通。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "查看与公安网安、行业监管、安全厂商及应急支撑单位的沟通记录。"),
    ("8.1.7.4-c", "安全管理机构", "沟通和合作", "应建立外联单位联系列表，包括外联单位名称、合作内容、联系人和联系方式等信息。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "核查并更新外联单位及安全厂商应急通讯录，验证信息准确性。"),
    ("8.1.7.5-a", "安全管理机构", "审核和检查", "应定期进行常规安全检查，检查内容包括系统日常运行、系统漏洞和数据备份等情况。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "查阅月度/季度常规安全巡检表、漏洞复查及备份状态核验记录。"),
    ("8.1.7.5-b", "安全管理机构", "审核和检查", "应定期进行全面安全检查，检查内容包括现有安全技术措施的有效性、安全配置与安全策略的一致性、安全管理制度的执行情况等。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "查阅年度全面安全自查方案、基线核查结果及制度执行审计记录。"),
    ("8.1.7.5-c", "安全管理机构", "审核和检查", "应制定安全检查表格实施安全检查，汇总安全检查数据，形成安全检查报告，并对安全检查结果进行通报。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "核查标准化检查表、汇总安全检查报告以及问题整改通报文件。"),

    # =========================================================================
    # 8.1.8 安全管理人员（4 个控制点，12 项）
    # =========================================================================
    ("8.1.8.1-a", "安全管理人员", "人员录用", "应指定或授权专门的部门或人员负责人员录用。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "核查人力资源部门或安全团队人员录用管理制度及职责分工。"),
    ("8.1.8.1-b", "安全管理人员", "人员录用", "应对被录用人员的身份、安全背景、专业资格或资质等进行审查，对其所具有的技术技能进行考核。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "抽查关键岗位新入职人员背景调查表、学历资质审核与技术面试/考核记录。"),
    ("8.1.8.1-c", "安全管理人员", "人员录用", "应与被录用人员签署保密协议，与关键岗位人员签署岗位责任协议。", "GENERAL", "MANUAL_ONLY", True, ["manual"], "抽查在岗人员已签署的保密协议及三员/核心运维岗位安全责任书。"),
    ("8.1.8.2-a", "安全管理人员", "人员离岗", "应及时终止离岗人员的所有访问权限，取回各种身份证件、钥匙、徽章等以及机构提供的软硬件设备。", "GENERAL", "MANUAL_ONLY", True, ["manual"], "抽查近一年离职/调岗人员权限回收单、账号注销截图与门禁卡/设备归还清单。"),
    ("8.1.8.2-b", "安全管理人员", "人员离岗", "应办理严格的调离手续，并承诺调离后的保密义务后方可离开。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "核查离职交接审批单及离岗保密承诺书签署档案。"),
    ("8.1.8.3-a", "安全管理人员", "安全意识教育和培训", "应对各类人员进行安全意识教育和岗位技能培训，并告知相关的安全责任和惩戒措施。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "查阅年度安全意识培训材料、签到记录以及安全责任与违规惩戒宣贯记录。"),
    ("8.1.8.3-b", "安全管理人员", "安全意识教育和培训", "应针对不同岗位制定不同的培训计划，对安全基础知识、岗位操作规程等进行培训。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "核查区分管理层、运维、研发与普通员工的年度培训计划及授课记录。"),
    ("8.1.8.3-c", "安全管理人员", "安全意识教育和培训", "应定期对不同岗位的人员进行技能考核。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "查阅安全培训考卷、在线答题成绩汇总及考核不通过补考记录。"),
    ("8.1.8.4-a", "安全管理人员", "外部人员访问管理", "应在外部人员物理访问受控区域前先提出书面申请，批准后由专人全程陪同，并登记备案。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "抽查外部人员进出机房书面申请单、审批签字、陪同记录与登记台账。"),
    ("8.1.8.4-b", "安全管理人员", "外部人员访问管理", "应在外部人员接入受控网络访问系统前先提出书面申请，批准后由专人开设账户、分配权限，并登记备案。", "GENERAL", "MANUAL_ONLY", True, ["manual"], "抽查外包/厂商远程或现场接入审批单、临时账号开通记录与授权范围。"),
    ("8.1.8.4-c", "安全管理人员", "外部人员访问管理", "外部人员离场后应及时清除其所有的访问权限。", "GENERAL", "MANUAL_ONLY", True, ["manual"], "核查外部人员项目结束或离场后的账号禁用/删除与 VPN/堡垒机权限清理记录。"),
    ("8.1.8.4-d", "安全管理人员", "外部人员访问管理", "获得系统访问授权的外部人员应签署保密协议，不得进行非授权操作，不得复制和泄露任何敏感信息。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "抽查驻场与外包人员保密协议签署件及堡垒机操作审计抽查记录。"),

    # =========================================================================
    # 8.1.9 安全建设管理（10 个控制点，34 项）
    # =========================================================================
    ("8.1.9.1-a", "安全建设管理", "定级和备案", "应以书面的形式说明保护对象的安全保护等级及确定等级的方法和理由。", "GENERAL", "MANUAL_ONLY", True, ["manual"], "查验系统《网络安全等级保护定级报告》并核对定级方法与业务/数据受侵害分析。"),
    ("8.1.9.1-b", "安全建设管理", "定级和备案", "应组织相关部门和有关安全技术专家对定级结果的合理性和正确性进行论证和审定。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "查验第三级系统定级专家评审意见表及评审会签到记录。"),
    ("8.1.9.1-c", "安全建设管理", "定级和备案", "应保证定级结果经过相关部门的批准。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "核查行业主管部门或本单位上级主管机构对定级结果的书面审核批准意见。"),
    ("8.1.9.1-d", "安全建设管理", "定级和备案", "应将备案材料报主管部门和相应公安机关备案。", "GENERAL", "MANUAL_ONLY", True, ["manual"], "查验公安机关出具的《信息系统安全等级保护备案证明》原件或扫描件。"),
    ("8.1.9.2-a", "安全建设管理", "安全方案设计", "应根据安全保护等级选择基本安全措施，依据风险分析的结果补充和调整安全措施。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "查阅系统安全需求分析报告、风险分析材料与安全措施选型对照表。"),
    ("8.1.9.2-b", "安全建设管理", "安全方案设计", "应根据保护对象的安全保护等级及与其他级别保护对象的关系进行安全整体规划和安全方案设计，设计内容应包含密码技术相关内容，并形成配套文件。", "GENERAL", "MANUAL_ONLY", True, ["manual"], "查验包含密码应用设计章节的《安全整体建设方案》及详细技术设计文档。"),
    ("8.1.9.2-c", "安全建设管理", "安全方案设计", "应组织相关部门和有关安全专家对安全整体规划及其配套文件的合理性和正确性进行论证和审定，经过批准后才能正式实施。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "查阅安全设计方案专家论证意见、修订记录及管理层批准实施文件。"),
    ("8.1.9.3-a", "安全建设管理", "产品采购和使用", "应确保网络安全产品采购和使用符合国家的有关规定。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "查验防火墙、WAF、堡垒机、日志审计等在用安全产品的计算机信息系统安全专用产品销售许可证/认证。"),
    ("8.1.9.3-b", "安全建设管理", "产品采购和使用", "应确保密码产品与服务的采购和使用符合国家密码管理主管部门的要求。", "GENERAL", "MANUAL_ONLY", True, ["manual"], "查验在用商用密码产品型号证书、密码模块安全认证或合规密码服务资质证明。"),
    ("8.1.9.3-c", "安全建设管理", "产品采购和使用", "应预先对产品进行选型测试，确定产品的候选范围，并定期审定和更新候选产品名单。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "查阅安全产品 POC 选型测试报告、合格产品短名单及年度审定记录。"),
    ("8.1.9.4-a", "安全建设管理", "自行软件开发", "应将开发环境与实际运行环境物理分开，测试数据和测试结果受到控制。", "GENERAL", "MANUAL_ONLY", True, ["manual"], "核查开发网、测试网与生产网隔离策略，确认测试环境未直接使用未经脱敏的生产数据。"),
    ("8.1.9.4-b", "安全建设管理", "自行软件开发", "应制定软件开发管理制度，明确说明开发过程的控制方法和人员行为准则。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "查阅《软件研发安全管理制度》及研发人员安全行为准则。"),
    ("8.1.9.4-c", "安全建设管理", "自行软件开发", "应制定代码编写安全规范，要求开发人员参照规范编写代码。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "查阅覆盖所用开发语言的安全编码规范及代码评审（Code Review）检查记录。"),
    ("8.1.9.4-d", "安全建设管理", "自行软件开发", "应具备软件设计的相关文档和使用指南，并对文档使用进行控制。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "核查需求规格、架构设计、接口文档、操作手册及文档仓库权限控制策略。"),
    ("8.1.9.4-e", "安全建设管理", "自行软件开发", "应保证在软件开发过程中对安全性进行测试，在软件安装前对可能存在的恶意代码进行检测。", "GENERAL", "PARTIAL_EVIDENCE", True, ["nuclei", "trivy_os"], "查阅上线前 SAST/DAST 安全测试报告、开源组件扫描及安装包病毒查杀记录。"),
    ("8.1.9.4-f", "安全建设管理", "自行软件开发", "应对程序资源库的修改、更新、发布进行授权和批准，并严格进行版本控制。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "核查 Git 分支保护、合并审批（MR/PR）、发版工单及制品库版本控制记录。"),
    ("8.1.9.4-g", "安全建设管理", "自行软件开发", "应保证开发人员为专职人员，开发人员的开发活动受到控制、监视和审查。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "核查专职开发团队名单、代码提交审计日志及开发账号与生产权限隔离措施。"),
    ("8.1.9.5-a", "安全建设管理", "外包软件开发", "应在软件交付前检测其中可能存在的恶意代码。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "查阅外包交付物查毒报告及第三方组件安全检查记录；无外包开发时可标为不适用。"),
    ("8.1.9.5-b", "安全建设管理", "外包软件开发", "应保证开发单位提供软件设计文档和使用指南。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "核查外包项目交付的概要设计、详细设计、部署手册与运维指南。"),
    ("8.1.9.5-c", "安全建设管理", "外包软件开发", "应保证开发单位提供软件源代码，并审查软件中可能存在的后门和隐蔽信道。", "GENERAL", "MANUAL_ONLY", True, ["manual"], "核查外包合同源码交付条款及交付后的代码安全审计、后门排查报告。"),
    ("8.1.9.6-a", "安全建设管理", "工程实施", "应指定或授权专门的部门或人员负责工程实施过程的管理。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "查阅项目经理/工程实施负责人任命书及实施团队职责文件。"),
    ("8.1.9.6-b", "安全建设管理", "工程实施", "应制定安全工程实施方案控制工程实施过程。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "查验经审批的《工程实施方案》、实施进度记录与变更控制单。"),
    ("8.1.9.6-c", "安全建设管理", "工程实施", "应通过第三方工程监理控制项目的实施过程。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "查阅第三方工程监理合同、监理日志及阶段验收监理报告。"),
    ("8.1.9.7-a", "安全建设管理", "测试验收", "应制订测试验收方案，并依据测试验收方案实施测试验收，形成测试验收报告。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "查验系统上线测试验收方案、测试用例执行记录及签字版《测试验收报告》。"),
    ("8.1.9.7-b", "安全建设管理", "测试验收", "应进行上线前的安全性测试，并出具安全测试报告，安全测试报告应包含密码应用安全性测试相关内容。", "GENERAL", "PARTIAL_EVIDENCE", True, ["nuclei", "tls_scanner"], "结合自动化扫描结果，查验上线前渗透测试、漏洞扫描及密码应用安全性评估报告。"),
    ("8.1.9.8-a", "安全建设管理", "系统交付", "应制定交付清单，并根据交付清单对所交接的设备、软件和文档等进行清点。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "查阅双方签字确认的设备、软件及文档交付清点清单。"),
    ("8.1.9.8-b", "安全建设管理", "系统交付", "应对负责运行维护的技术人员进行相应的技能培训。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "核查系统移交阶段的运维技术培训签到表、课件及考核记录。"),
    ("8.1.9.8-c", "安全建设管理", "系统交付", "应提供建设过程文档和运行维护文档。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "核查设计文档、部署手册、应急操作手册与日常维护文档归档完整性。"),
    ("8.1.9.9-a", "安全建设管理", "等级测评", "应定期进行等级测评，发现不符合相应等级保护标准要求的及时整改。", "GENERAL", "MANUAL_ONLY", True, ["manual"], "查验最近一次年度等保三级正式测评报告以及针对不符合项的整改验证记录。"),
    ("8.1.9.9-b", "安全建设管理", "等级测评", "应在发生重大变更或级别发生变化时进行等级测评。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "核查制度中关于架构重大变更、迁移或定级调整后重新测评的规定与执行记录。"),
    ("8.1.9.9-c", "安全建设管理", "等级测评", "应确保测评机构的选择符合国家有关规定。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "查验所选测评机构的《网络安全等级测评与检测评估机构服务认证证书》有效期。"),
    ("8.1.9.10-a", "安全建设管理", "服务供应商选择", "应确保服务供应商的选择符合国家的有关规定。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "核查安全服务商营业执照、信息安全服务资质及入围审查材料。"),
    ("8.1.9.10-b", "安全建设管理", "服务供应商选择", "应与选定的服务供应商签订相关协议，明确整个服务供应链各方需履行的网络安全相关义务。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "查阅服务合同及网络安全保密协议中的权责划分与违约条款。"),
    ("8.1.9.10-c", "安全建设管理", "服务供应商选择", "应定期监督、评审和审核服务供应商提供的服务，并对其变更服务内容加以控制。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "查阅供应商年度服务质量与安全评审记录及服务变更审批记录。"),

    # =========================================================================
    # 8.1.10 安全运维管理（14 个控制点，48 项）
    # =========================================================================
    ("8.1.10.1-a", "安全运维管理", "环境管理", "应指定专门的部门或人员负责机房安全，对机房出入进行管理，定期对机房供配电、空调、温湿度控制、消防等设施进行维护管理。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "查阅机房安全责任人清单及供配电、空调、消防设施定期维保巡检台账。"),
    ("8.1.10.1-b", "安全运维管理", "环境管理", "应建立机房安全管理制度，对有关物理访问、物品带进出和环境安全等方面的管理作出规定。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "核查《机房安全管理制度》以及设备/物品进出机房登记审批表。"),
    ("8.1.10.1-c", "安全运维管理", "环境管理", "应不在重要区域接待来访人员，不随意放置含有敏感信息的纸档文件和移动介质等。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "现场检查机房及运维控制室，确认无无关访客滞留且无随意摆放的敏感纸质资料和 U 盘。"),
    ("8.1.10.2-a", "安全运维管理", "资产管理", "应编制并保存与保护对象相关的资产清单，包括资产责任部门、重要程度和所处位置等内容。", "GENERAL", "PARTIAL_EVIDENCE", False, ["targets"], "对照工作台纳管资产清单，核查正式 IT 资产台账是否涵盖责任部门、重要程度与物理/逻辑位置。"),
    ("8.1.10.2-b", "安全运维管理", "资产管理", "应根据资产的重要程度对资产进行标识管理，根据资产的价值选择相应的管理措施。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "查阅资产分类分级标准及核心/重要/一般资产的差异化保护与盘点记录。"),
    ("8.1.10.2-c", "安全运维管理", "资产管理", "应对信息分类与标识方法作出规定，并对信息的使用、传输和存储等进行规范化管理。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "查阅《数据分类分级管理办法》及敏感数据使用、传输、存储的标注与管控记录。"),
    ("8.1.10.3-a", "安全运维管理", "介质管理", "应将介质存放在安全的环境中，对各类介质进行控制和保护，实行存储环境专人管理，并根据存档介质的目录清单定期盘点。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "核查备份磁带/光盘/加密硬盘专用存放柜、专人台账及定期盘点记录。"),
    ("8.1.10.3-b", "安全运维管理", "介质管理", "应对介质在物理传输过程中的人员选择、打包、交付等情况进行控制，并对介质的归档和查询等进行登记记录。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "核查介质借用、送外存放、归档与销毁审批登记表。"),
    ("8.1.10.4-a", "安全运维管理", "设备维护管理", "应对各种设备（包括备份和冗余设备）、线路等指定专门的部门或人员定期进行维护管理。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "查阅服务器、网络设备、备品备件及线路的定期维保计划与执行记录。"),
    ("8.1.10.4-b", "安全运维管理", "设备维护管理", "应建立配套设施、软硬件维护方面的管理制度，对其维护进行有效的管理，包括明确维护人员的责任、维修和服务的审批、维修过程的监督控制等。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "查阅《设备维护管理制度》及设备报修审批单、厂商现场维修陪同记录。"),
    ("8.1.10.4-c", "安全运维管理", "设备维护管理", "信息处理设备应经过审批才能带离机房或办公地点，含有存储介质的设备带出工作环境时其中重要数据应加密。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "抽查设备带出审批单及涉敏硬盘加密/数据擦除确认记录。"),
    ("8.1.10.4-d", "安全运维管理", "设备维护管理", "含有存储介质的设备在报废或重用前，应进行完全清除或被安全覆盖，保证该设备上的敏感数据和授权软件无法被恢复重用。", "GENERAL", "MANUAL_ONLY", True, ["manual"], "查阅报废或调拨设备的磁盘消磁、安全覆写或物理销毁记录及审批单。"),
    ("8.1.10.5-a", "安全运维管理", "漏洞和风险管理", "应采取必要的措施识别安全漏洞和隐患，对发现的安全漏洞和隐患及时进行修补或评估可能的影响后进行修补。", "GENERAL", "FULL_AUTO", True, ["trivy_os", "nuclei", "defectdojo"], "依据软件包 CVE 漏洞扫描、Web 模板核查及 DefectDojo 整改闭环记录评估。"),
    ("8.1.10.5-b", "安全运维管理", "漏洞和风险管理", "应定期开展安全测评，形成安全测评报告，采取措施应对发现的安全问题。", "GENERAL", "PARTIAL_EVIDENCE", True, ["defectdojo"], "查阅定期渗透测试、漏洞扫描及预评估报告，以及对应问题的整改闭环证据。"),
    ("8.1.10.6-a", "安全运维管理", "网络和系统安全管理", "应划分不同的管理员角色进行网络和系统的运维管理，明确各个角色的责任和权限。", "GENERAL", "PARTIAL_EVIDENCE", False, ["ssh_baseline"], "核查网络管理员、系统管理员、数据库管理员等角色划分文件及实际账户权限对应表。"),
    ("8.1.10.6-b", "安全运维管理", "网络和系统安全管理", "应指定专门的部门或人员进行账户管理，对申请账户、建立账户、删除账户等进行控制。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "抽查账户全生命周期管理审批单及定期多余账户核查记录。"),
    ("8.1.10.6-c", "安全运维管理", "网络和系统安全管理", "应建立网络和系统安全管理制度，对安全策略、账户管理、配置管理、日志管理、日常操作、升级与打补丁、口令更新周期等方面作出规定。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "核查《网络和系统安全管理制度》是否覆盖口令周期、补丁升级、日志与日常操作规范。"),
    ("8.1.10.6-d", "安全运维管理", "网络和系统安全管理", "应制定重要设备的配置和操作手册，依据手册对设备进行安全配置和优化配置等。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "查阅核心网络设备、安全设备、操作系统与数据库的安全基线配置手册。"),
    ("8.1.10.6-e", "安全运维管理", "网络和系统安全管理", "应详细记录运维操作日志，包括日常巡检工作、运行维护记录、参数的设置和修改等内容。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "抽查日常巡检台账、运维工单系统记录及堡垒机操作日志。"),
    ("8.1.10.6-f", "安全运维管理", "网络和系统安全管理", "应指定专门的部门或人员对日志、监测和报警数据等进行分析、统计，及时发现可疑行为。", "GENERAL", "MANUAL_ONLY", True, ["manual"], "查阅日志审计与告警分析周报/月报及异常告警处置闭环记录。"),
    ("8.1.10.6-g", "安全运维管理", "网络和系统安全管理", "应严格控制变更性运维，经过审批后才可改变连接、安装系统组件或调整配置参数，操作过程中应保留不可更改的审计日志，操作结束后应同步更新配置信息库。", "GENERAL", "MANUAL_ONLY", True, ["manual"], "抽查生产环境变更工单、堡垒机操作审计录像及 CMDB 配置更新记录。"),
    ("8.1.10.6-h", "安全运维管理", "网络和系统安全管理", "应严格控制运维工具的使用，经过审批后才可接入进行操作，操作过程中应保留不可更改的审计日志，操作结束后应删除工具中的敏感数据。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "核查运维工具入网审批记录、接入操作审计日志及使用后缓存清理确认单。"),
    ("8.1.10.6-i", "安全运维管理", "网络和系统安全管理", "应严格控制远程运维的开通，经过审批后才可开通远程运维接口或通道，操作过程中应保留不可更改的审计日志，操作结束后立即关闭接口或通道。", "GENERAL", "PARTIAL_EVIDENCE", True, ["nmap", "ssh_baseline"], "结合暴露管理端口核查，查验远程运维审批单、堡垒机审计录像及事后关闭记录。"),
    ("8.1.10.6-j", "安全运维管理", "网络和系统安全管理", "应保证所有与外部的连接均得到授权和批准，应定期检查违反规定无线上网及其他违反网络安全策略的行为。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "查验外部专线/互联网出口审批台账及定期违规外联、违规无线上网检查记录。"),
    ("8.1.10.7-a", "安全运维管理", "恶意代码防范管理", "应提高所有用户的防恶意代码意识，对外来计算机或存储设备接入系统前进行恶意代码检查等。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "查阅防病毒管理制度、外来介质入网查杀记录及员工防钓鱼/防病毒宣贯材料。"),
    ("8.1.10.7-b", "安全运维管理", "恶意代码防范管理", "应定期验证防范恶意代码攻击的技术措施的有效性。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "查验防病毒软件/EDR 病毒库更新巡检、查杀统计及防护有效性测试记录。"),
    ("8.1.10.8-a", "安全运维管理", "配置管理", "应记录和保存基本配置信息，包括网络拓扑结构、各个设备安装的软件组件、软件组件的版本和补丁信息、各个设备或软件组件的配置参数等。", "GENERAL", "PARTIAL_EVIDENCE", False, ["targets", "trivy_os"], "核查 CMDB/配置管理台账、最新网络拓扑图及设备软件版本和补丁基线清单。"),
    ("8.1.10.8-b", "安全运维管理", "配置管理", "应将基本配置信息改变纳入变更范畴，实施对配置信息改变的控制，并及时更新基本配置信息库。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "抽查配置变更单与 CMDB 同步更新记录，确认配置库与现网一致。"),
    ("8.1.10.9-a", "安全运维管理", "密码管理", "应遵循密码相关国家标准和行业标准。", "GENERAL", "PARTIAL_EVIDENCE", True, ["tls_scanner"], "核查密码管理制度及系统采用国密/合规密码算法的符合性说明或密评报告。"),
    ("8.1.10.9-b", "安全运维管理", "密码管理", "应使用国家密码管理主管部门认证核准的密码技术和产品。", "GENERAL", "MANUAL_ONLY", True, ["manual"], "查验在用密钥管理、加解密模块与数字证书服务的商用密码产品认证及合规证明。"),
    ("8.1.10.10-a", "安全运维管理", "变更管理", "应明确变更需求，变更前根据变更需求制定变更方案，变更方案经过评审、审批后方可实施。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "抽查近期系统与网络变更需求说明、变更实施方案及评审审批记录。"),
    ("8.1.10.10-b", "安全运维管理", "变更管理", "应建立变更的申报和审批控制程序，依据程序控制所有的变更，记录变更实施过程。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "查验《变更管理制度》及变更工单全流程记录（申报、审批、实施、验证）。"),
    ("8.1.10.10-c", "安全运维管理", "变更管理", "应建立中止变更并从失败变更中恢复的程序，明确过程控制方法和人员职责，必要时对恢复过程进行演练。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "核查变更回退预案模板、失败回退职责说明及关键系统回退演练记录。"),
    ("8.1.10.11-a", "安全运维管理", "备份与恢复管理", "应识别需要定期备份的重要业务信息、系统数据及软件系统等。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "查阅重要数据与系统备份对象清单及备份范围评审记录。"),
    ("8.1.10.11-b", "安全运维管理", "备份与恢复管理", "应规定备份信息的备份方式、备份频度、存储介质、保存期等。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "核查《数据备份与恢复管理制度》中全量/增量备份周期、介质与留存期限规定。"),
    ("8.1.10.11-c", "安全运维管理", "备份与恢复管理", "应根据数据的重要性和数据对系统运行的影响，制定数据的备份策略和恢复策略、备份程序和恢复程序等。", "GENERAL", "MANUAL_ONLY", True, ["manual"], "查阅备份与恢复策略手册、自动备份成功日志以及年度数据恢复演练报告。"),
    ("8.1.10.12-a", "安全运维管理", "安全事件处置", "应及时向安全管理部门报告所发现的安全弱点和可疑事件。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "核查安全事件上报渠道、值守电话及内部安全隐患上报记录。"),
    ("8.1.10.12-b", "安全运维管理", "安全事件处置", "应制定安全事件报告和处置管理制度，明确不同安全事件的报告、处置和响应流程，规定安全事件的现场处理、事件报告和后期恢复的管理职责等。", "GENERAL", "MANUAL_ONLY", True, ["manual"], "查阅《网络安全事件报告与处置管理制度》，核对事件分级与各环节责任分工。"),
    ("8.1.10.12-c", "安全运维管理", "安全事件处置", "应在安全事件报告和响应处理过程中，分析和鉴定事件产生的原因，收集证据，记录处理过程，总结经验教训。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "查阅历史安全事件处置报告、取证留存材料及复盘改进记录。"),
    ("8.1.10.12-d", "安全运维管理", "安全事件处置", "对造成系统中断和造成信息泄漏的重大安全事件应采用不同的处理程序和报告程序。", "GENERAL", "MANUAL_ONLY", True, ["manual"], "核查制度中是否针对业务中断类与数据泄漏类重大事件分别制定差异化响应与监管上报流程。"),
    ("8.1.10.13-a", "安全运维管理", "应急预案管理", "应规定统一的应急预案框架，包括启动预案的条件、应急组织构成、应急资源保障、事后教育和培训等内容。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "查阅单位《网络安全总体应急预案》，核对组织架构、启动条件与资源保障条款。"),
    ("8.1.10.13-b", "安全运维管理", "应急预案管理", "应制定重要事件的应急预案，包括应急处理流程、系统恢复流程等内容。", "GENERAL", "MANUAL_ONLY", True, ["manual"], "查阅勒索病毒、网页篡改、DDoS、数据库故障、数据泄漏等专项应急处置预案。"),
    ("8.1.10.13-c", "安全运维管理", "应急预案管理", "应定期对系统相关的人员进行应急预案培训，并进行应急预案的演练。", "GENERAL", "MANUAL_ONLY", True, ["manual"], "查验年度应急预案培训记录、应急演练方案、演练过程照片及演练总结报告。"),
    ("8.1.10.13-d", "安全运维管理", "应急预案管理", "应定期对原有的应急预案重新评估，修订完善。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "查阅演练后应急预案评估意见及版本修订发布记录。"),
    ("8.1.10.14-a", "安全运维管理", "外包运维管理", "应确保外包运维服务商的选择符合国家的有关规定。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "核查外包运维单位资质证明与准入评估记录；无外包运维时可标为不适用。"),
    ("8.1.10.14-b", "安全运维管理", "外包运维管理", "应与选定的外包运维服务商签订相关的协议，明确约定外包运维的范围、工作内容。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "查验外包运维服务合同及 SLA 范围附件。"),
    ("8.1.10.14-c", "安全运维管理", "外包运维管理", "应保证选择的外包运维服务商在技术和管理方面均应具有按照等级保护要求开展安全运维工作的能力，并将能力要求在签订的协议中明确。", "GENERAL", "MANUAL_ONLY", False, ["manual"], "核查外包运维团队人员资质证书及合同中的等保合规履约条款。"),
    ("8.1.10.14-d", "安全运维管理", "外包运维管理", "应在与外包运维服务商签订的协议中明确所有相关的安全要求，如可能涉及对敏感信息的访问、处理、存储要求，对 IT 基础设施中断服务的应急保障要求等。", "GENERAL", "MANUAL_ONLY", True, ["manual"], "核查外包合同与保密协议中的敏感数据保护、应急响应时效及违约责任约定。"),

    # =========================================================================
    # 8.2 云计算安全扩展要求（16 个控制点，46 项）
    # =========================================================================
    # 8.2.1 安全物理环境（1 项）
    ("8.2.1.1-a", "云计算安全扩展", "基础设施位置", "应保证云计算基础设施位于中国境内。", "CLOUD", "PARTIAL_EVIDENCE", True, ["cloud_audit"], "结合云平台只读核查导入的地域（Region）结果，核查云服务合同及云服务商数据中心境内声明。"),

    # 8.2.2 安全通信网络（5 项）
    ("8.2.2.1-a", "云计算安全扩展", "网络架构", "应保证云计算平台不承载高于其安全保护等级的业务应用系统。", "CLOUD", "PARTIAL_EVIDENCE", True, ["cloud_audit"], "结合云平台只读核查导入的平台定级信息，查验所用云计算平台（IaaS/PaaS）的等保三级或以上备案证明与测评结论。"),
    ("8.2.2.1-b", "云计算安全扩展", "网络架构", "应实现不同云服务客户虚拟网络之间的隔离。", "CLOUD", "PARTIAL_EVIDENCE", True, ["cloud_audit", "ecloud"], "核查 VPC 专有网络划分、租户虚拟网络隔离技术说明及安全组隔离策略。"),
    ("8.2.2.1-c", "云计算安全扩展", "网络架构", "应具有根据云服务客户业务需求提供通信传输、边界防护、入侵防范等安全机制的能力。", "CLOUD", "MANUAL_ONLY", False, ["manual"], "核查云平台是否提供云防火墙、安全组、加密通道及云入侵检测等可选安全能力。"),
    ("8.2.2.1-d", "云计算安全扩展", "网络架构", "应具有根据云服务客户业务需求自主设置安全策略的能力，包括定义访问路径、选择安全组件、配置安全策略。", "CLOUD", "PARTIAL_EVIDENCE", False, ["cloud_audit", "ecloud"], "核查云租户控制台路由表、安全组、网络 ACL 及云 WAF 自主编排配置记录。"),
    ("8.2.2.1-e", "云计算安全扩展", "网络架构", "应提供开放接口或开放性安全服务，允许云服务客户接入第三方安全产品或在云计算平台选择第三方安全服务。", "CLOUD", "MANUAL_ONLY", False, ["manual"], "核查云平台云市场第三方安全镜像或开放 API 接口接入说明。"),

    # 8.2.3 安全区域边界（8 项）
    ("8.2.3.1-a", "云计算安全扩展", "边界访问控制", "应在虚拟化网络边界部署访问控制机制，并设置访问控制规则。", "CLOUD", "PARTIAL_EVIDENCE", True, ["cloud_audit", "ecloud", "nmap"], "结合云安全组核查导入结果，核查云边界防火墙、VPC 安全组及子网 ACL 规则最小授权。"),
    ("8.2.3.1-b", "云计算安全扩展", "边界访问控制", "应在不同等级的网络区域边界部署访问控制机制，设置访问控制规则。", "CLOUD", "PARTIAL_EVIDENCE", True, ["cloud_audit", "ecloud"], "核查不同安全等级 VPC/子网之间的对等连接路由与安全组边界控制策略。"),
    ("8.2.3.2-a", "云计算安全扩展", "边界入侵防范", "应能检测到云服务客户发起的网络攻击行为，并能记录攻击类型、攻击时间、攻击流量等。", "CLOUD", "MANUAL_ONLY", True, ["manual"], "核查云防火墙或云安全中心对外发异常攻击行为的检测与日志记录能力。"),
    ("8.2.3.2-b", "云计算安全扩展", "边界入侵防范", "应能检测到对虚拟网络节点的网络攻击行为，并能记录攻击类型、攻击时间、攻击流量等。", "CLOUD", "MANUAL_ONLY", True, ["manual"], "核查云 IPS/云防火墙对云主机、负载均衡及虚拟网关受攻击行为的检测日志。"),
    ("8.2.3.2-c", "云计算安全扩展", "边界入侵防范", "应能检测到虚拟机与宿主机、虚拟机与虚拟机之间的异常流量。", "CLOUD", "MANUAL_ONLY", True, ["manual"], "核查云平台虚拟化东西向流量监测与虚拟机逃逸/横向扫描检测机制。"),
    ("8.2.3.2-d", "云计算安全扩展", "边界入侵防范", "应在检测到网络攻击行为、异常流量情况时进行告警。", "CLOUD", "PARTIAL_EVIDENCE", True, ["cloud_audit"], "结合云操作审计与告警配置核查导入结果，查验云安全告警策略及历史通知记录。"),
    ("8.2.3.3-a", "云计算安全扩展", "边界安全审计", "应对云服务商和云服务客户在远程管理时执行的特权命令进行审计，至少包括虚拟机删除、虚拟机重启。", "CLOUD", "PARTIAL_EVIDENCE", True, ["cloud_audit"], "结合云操作审计（CloudTrail/ActionTrail）核查导入结果，验证对云主机创建、重启、删除及安全组变更的日志记录。"),
    ("8.2.3.3-b", "云计算安全扩展", "边界安全审计", "应保证云服务商对云服务客户系统和数据的操作可被云服务客户审计。", "CLOUD", "MANUAL_ONLY", False, ["manual"], "核查云服务商运维协助授权记录及租户侧可查验的平台操作审计接口或工单日志。"),

    # 8.2.4 安全计算环境（19 项）
    ("8.2.4.1-a", "云计算安全扩展", "身份鉴别", "当远程管理云计算平台中设备时，管理终端和云计算平台之间应建立双向身份验证机制。", "CLOUD", "PARTIAL_EVIDENCE", True, ["cloud_audit"], "结合云 IAM/RAM MFA 配置导入结果，核查云平台管理端与运维终端之间的双向身份认证机制。"),
    ("8.2.4.2-a", "云计算安全扩展", "访问控制", "应保证当虚拟机迁移时，访问控制策略随其迁移。", "CLOUD", "MANUAL_ONLY", True, ["manual"], "核查云平台热迁移/冷迁移机制说明及迁移测试记录，确认安全组和访问规则同步保持。"),
    ("8.2.4.2-b", "云计算安全扩展", "访问控制", "应允许云服务客户设置不同虚拟机之间的访问控制策略。", "CLOUD", "PARTIAL_EVIDENCE", True, ["cloud_audit", "ecloud"], "核查同一 VPC 内不同云主机间的安全组互访策略与端口精细化控制配置。"),
    ("8.2.4.3-a", "云计算安全扩展", "入侵防范", "应能检测虚拟机之间的资源隔离失效，并进行告警。", "CLOUD", "MANUAL_ONLY", True, ["manual"], "查验云平台或虚拟化层资源隔离监控、异常越界检测及告警记录（结合云商测评报告）。"),
    ("8.2.4.3-b", "云计算安全扩展", "入侵防范", "应能检测非授权新建虚拟机或者重新启用虚拟机，并进行告警。", "CLOUD", "PARTIAL_EVIDENCE", True, ["cloud_audit"], "结合云操作审计告警配置导入结果，核查未审批创建/启动云主机时是否触发实时告警。"),
    ("8.2.4.3-c", "云计算安全扩展", "入侵防范", "应能够检测恶意代码感染及在虚拟机间蔓延的情况，并进行告警。", "CLOUD", "PARTIAL_EVIDENCE", True, ["ssh_baseline"], "核查云主机安全 Agent（HIDS/EDR）对病毒木马感染及跨主机横向扩散的检测告警配置。"),
    ("8.2.4.4-a", "云计算安全扩展", "镜像和快照保护", "应针对重要业务系统提供加固的操作系统镜像或操作系统安全加固服务。", "CLOUD", "PARTIAL_EVIDENCE", True, ["trivy_os", "ssh_baseline"], "结合主机基线与软件包漏洞结果，核查是否采用经安全基线加固的黄金镜像。"),
    ("8.2.4.4-b", "云计算安全扩展", "镜像和快照保护", "应提供虚拟机镜像、快照完整性校验功能，防止虚拟机镜像被恶意篡改。", "CLOUD", "PARTIAL_EVIDENCE", True, ["cloud_audit"], "结合云镜像与快照完整性核查导入结果，查验云镜像仓库哈希签名校验与发布审批记录。"),
    ("8.2.4.4-c", "云计算安全扩展", "镜像和快照保护", "应采取密码技术或其他技术手段防止虚拟机镜像、快照中可能存在的敏感资源被非法访问。", "CLOUD", "PARTIAL_EVIDENCE", True, ["cloud_audit"], "结合云镜像加密核查导入结果，核查私有镜像加密存储、访问权限控制及敏感凭据清理流程。"),
    ("8.2.4.5-a", "云计算安全扩展", "数据完整性和保密性", "应确保云服务客户数据、用户个人信息等存储于中国境内，如需出境应遵循国家相关规定。", "CLOUD", "PARTIAL_EVIDENCE", True, ["cloud_audit"], "结合云地域合规核查导入结果，核查云数据库、对象存储与日志存储地域均位于中国境内。"),
    ("8.2.4.5-b", "云计算安全扩展", "数据完整性和保密性", "应确保只有在云服务客户授权下，云服务商或第三方才具有云服务客户数据的管理权限。", "CLOUD", "PARTIAL_EVIDENCE", True, ["cloud_audit"], "结合云 IAM 最小权限与 AK 核查导入结果，核查云服务协议数据主权条款及临时授权工单。"),
    ("8.2.4.5-c", "云计算安全扩展", "数据完整性和保密性", "应使用校验码或密码技术确保虚拟机迁移过程中重要数据的完整性，并在检测到完整性受到破坏时采取必要的恢复措施。", "CLOUD", "MANUAL_ONLY", False, ["manual"], "查阅云平台虚拟机迁移加密与完整性校验技术文档或云服务商等保测评引用证明。"),
    ("8.2.4.5-d", "云计算安全扩展", "数据完整性和保密性", "应支持云服务客户部署密钥管理解决方案，保证云服务客户自行实现数据的加解密过程。", "CLOUD", "PARTIAL_EVIDENCE", True, ["cloud_audit"], "结合云 KMS/BYOK 核查导入结果，核查租户自主密钥管理与加解密配置。"),
    ("8.2.4.6-a", "云计算安全扩展", "数据备份恢复", "云服务客户应在本地保存其业务数据的备份。", "CLOUD", "PARTIAL_EVIDENCE", True, ["cloud_audit"], "结合云备份策略核查导入结果，核查云上核心业务数据定期拉回本地机房或独立灾备域的备份留存记录。"),
    ("8.2.4.6-b", "云计算安全扩展", "数据备份恢复", "应提供查询云服务客户数据及备份存储位置的能力。", "CLOUD", "MANUAL_ONLY", False, ["manual"], "验证在云控制台或服务协议中可清晰查询业务数据与备份副本所在地域及可用区。"),
    ("8.2.4.6-c", "云计算安全扩展", "数据备份恢复", "云服务商的云存储服务应保证云服务客户数据存在若干个可用的副本，各副本之间的内容应保持一致。", "CLOUD", "MANUAL_ONLY", False, ["manual"], "核查云盘/对象存储多副本或跨可用区冗余配置与数据一致性说明。"),
    ("8.2.4.6-d", "云计算安全扩展", "数据备份恢复", "应为云服务客户将业务系统及数据迁移到其他云计算平台和本地系统提供技术手段，并协助完成迁移过程。", "CLOUD", "MANUAL_ONLY", False, ["manual"], "核查云平台镜像导出、数据库逻辑导出工具及云服务退出迁移保障条款。"),
    ("8.2.4.7-a", "云计算安全扩展", "剩余信息保护", "应保证虚拟机所使用的内存和存储空间回收时得到完全清除。", "CLOUD", "MANUAL_ONLY", True, ["manual"], "核查云平台虚拟机销毁、云盘释放时内存清零与存储块覆盖机制说明及云商测评证明。"),
    ("8.2.4.7-b", "云计算安全扩展", "剩余信息保护", "云服务客户删除业务应用数据时，云计算平台应将云存储中所有副本删除。", "CLOUD", "MANUAL_ONLY", False, ["manual"], "核查云存储数据删除及多副本同步清理策略与云服务商技术承诺。"),

    # 8.2.5 安全管理中心（4 项）
    ("8.2.5.1-a", "云计算安全扩展", "集中管控", "应能对物理资源和虚拟资源按照策略做统一管理调度与分配。", "CLOUD", "MANUAL_ONLY", False, ["manual"], "查验云管理平台资源配额管理、虚拟资源统一调度与监控界面。"),
    ("8.2.5.1-b", "云计算安全扩展", "集中管控", "应保证云计算平台管理流量与云服务客户业务流量分离。", "CLOUD", "MANUAL_ONLY", True, ["manual"], "核查云平台管理平面与租户业务平面网络逻辑或物理隔离架构说明。"),
    ("8.2.5.1-c", "云计算安全扩展", "集中管控", "应根据云服务商和云服务客户的职责划分，收集各自控制部分的审计数据并实现各自的集中审计。", "CLOUD", "PARTIAL_EVIDENCE", True, ["cloud_audit"], "结合云操作审计与留存周期核查导入结果，核查云平台侧与租户侧审计日志集中留存六个月以上。"),
    ("8.2.5.1-d", "云计算安全扩展", "集中管控", "应根据云服务商和云服务客户的职责划分，实现各自控制部分，包括虚拟化网络、虚拟机、虚拟化安全设备等的运行状况的集中监测。", "CLOUD", "MANUAL_ONLY", False, ["manual"], "查验云监控平台对云主机、虚拟网络及云安全组件运行指标的集中监控面板。"),

    # 8.2.6 安全建设管理（8 项）
    ("8.2.6.1-a", "云计算安全扩展", "云服务商选择", "应选择安全合规的云服务商，其所提供的云计算平台应为其所承载的业务应用系统提供相应等级的安全保护能力。", "CLOUD", "PARTIAL_EVIDENCE", True, ["cloud_audit"], "结合云平台定级核查导入结果，查验云服务商等保三级及以上备案证明与安全评估资质。"),
    ("8.2.6.1-b", "云计算安全扩展", "云服务商选择", "应在服务水平协议中规定云服务的各项服务内容和具体技术指标。", "CLOUD", "MANUAL_ONLY", False, ["manual"], "查阅云服务合同及 SLA 协议中的可用性指标、故障恢复时间与服务内容条款。"),
    ("8.2.6.1-c", "云计算安全扩展", "云服务商选择", "应在服务水平协议中规定云服务商的权限与责任，包括管理范围、职责划分、访问授权、隐私保护、行为准则、违约责任等。", "CLOUD", "MANUAL_ONLY", True, ["manual"], "查验云服务责任共担矩阵及合同中关于权限、隐私保护与违约追责条款。"),
