def normalize_extensions(extensions: Iterable[str] | None) -> list[str]:
    """规范化项目启用的条款扩展包，始终包含安全通用要求 GENERAL。"""
    result = ["GENERAL"]
    for item in extensions or []:
        key = str(item or "").strip().upper()
        if key in ALL_EXTENSIONS and key not in result:
            result.append(key)
    return result


def build_catalog() -> list[dict]:
    from core.clause_metadata import enrich_clause

    rows: list[dict] = []
    seen: set[str] = set()
    for clause_id, domain, point, text, ext, auto, high, sources, guide in CLAUSES_SPEC:
        if clause_id in seen:
            raise ValueError(f"重复的条款编号：{clause_id}")
        seen.add(clause_id)
        rows.append(enrich_clause({
            "clause_id": clause_id,
            "domain": domain,
            "control_point": point,
            "requirement_text": text,
            "extension_type": ext,
            "auto_level": auto,
            "high_risk": high,
            "expected_evidence_sources": sources,
            "manual_check_guide": guide,
        }))
    return rows


def catalog_path() -> Path:
    return Path(__file__).resolve().parents[2] / "config" / "mlps3_clauses.json"


def load_clauses(extensions: Iterable[str] | None = None) -> list[dict]:
    """读取条款库；传入 extensions 时按项目启用的扩展包过滤。"""
    from core.clause_metadata import enrich_clause

    path = catalog_path()
    rows = json.loads(path.read_text(encoding="utf-8")) if path.exists() else build_catalog()
    rows = [enrich_clause(row) for row in rows]
    if extensions is None:
        return rows
    allowed = set(normalize_extensions(extensions))
    return [row for row in rows if str(row.get("extension_type") or "GENERAL").upper() in allowed]


def write_catalog(path: Path | None = None) -> list[dict]:
    target = path or catalog_path()
    rows = build_catalog()
    target.write_text(json.dumps(rows, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    return rows


if __name__ == "__main__":
    rows = write_catalog()
    by_ext: dict[str, int] = {}
    by_domain: dict[str, int] = {}
    for row in rows:
        by_ext[row["extension_type"]] = by_ext.get(row["extension_type"], 0) + 1
        by_domain[row["domain"]] = by_domain.get(row["domain"], 0) + 1
    print(f"TOTAL={len(rows)} EXT={by_ext}")
    for domain, count in by_domain.items():
        print(f"  {domain}: {count}")
